SELECT i.inv_item_sk, w.w_warehouse_id, w.w_warehouse_name, i.inv_quantity_on_hand, CASE WHEN i.inv_quantity_on_hand > 100 THEN 'High' WHEN i.inv_quantity_on_hand > 0 THEN 'Low' ELSE 'Out of Stock' END AS stock_status, w.w_gmt_offset * 2 AS offset_double, CONCAT(w.w_city, ', ', w.w_state) AS location FROM inventory i JOIN warehouse w ON i.inv_warehouse_sk = w.w_warehouse_sk WHERE i.inv_date_sk BETWEEN 2451088 AND 2450927 AND w.w_state = 'NY'
